import{_ as a,o as t,c as o,ah as r}from"./chunks/framework.D4KxWb5R.js";const m=JSON.parse('{"title":"Frequently asked questions","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/faq.md","filePath":"src/en/guide/faq.md"}'),n={name:"en/guide/faq.md"};function i(s,e,c,d,h,l){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="frequently-asked-questions" tabindex="-1">Frequently asked questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to &quot;Frequently asked questions&quot;">​</a></h1><h2 id="i-didn-t-receive-my-invitation" tabindex="-1">I didn&#39;t receive my invitation <a class="header-anchor" href="#i-didn-t-receive-my-invitation" aria-label="Permalink to &quot;I didn&#39;t receive my invitation&quot;">​</a></h2><p>Check your spam folder. Otherwise, ask the administrator to <a href="./administration/accounts.html">resend it</a>: the new e-mail carries a new temporary password, and the old one stops working.</p><h2 id="my-temporary-password-no-longer-works" tabindex="-1">My temporary password no longer works <a class="header-anchor" href="#my-temporary-password-no-longer-works" aria-label="Permalink to &quot;My temporary password no longer works&quot;">​</a></h2><p>It has expired (7 days by default). Ask the administrator to resend the invitation.</p><h2 id="i-don-t-receive-the-sign-in-code" tabindex="-1">I don&#39;t receive the sign-in code <a class="header-anchor" href="#i-don-t-receive-the-sign-in-code" aria-label="Permalink to &quot;I don&#39;t receive the sign-in code&quot;">​</a></h2><p>Wait a minute, check your spam folder, then click <strong>Send a new code</strong>. The code is valid for 15 minutes. If e-mails still don&#39;t arrive, contact the administrator.</p><h2 id="i-can-t-see-a-product" tabindex="-1">I can&#39;t see a product <a class="header-anchor" href="#i-can-t-see-a-product" aria-label="Permalink to &quot;I can&#39;t see a product&quot;">​</a></h2><p>Your scope doesn&#39;t cover it. Ask your head of unit or the administrator to add it to your account or your team.</p><h2 id="the-intranet-works-but-not-a-product-s-back-office" tabindex="-1">The intranet works, but not a product&#39;s back-office <a class="header-anchor" href="#the-intranet-works-but-not-a-product-s-back-office" aria-label="Permalink to &quot;The intranet works, but not a product&#39;s back-office&quot;">​</a></h2><p>Access to a product&#39;s back-office is granted separately. Ask the administrator for it (see <a href="./administration/accounts.html">Accounts</a>). For Auticway, see also the <a href="./auticway.html#refusal-messages">refusal messages</a>.</p><h2 id="i-can-t-attach-a-zone-to-a-product" tabindex="-1">I can&#39;t attach a zone to a product <a class="header-anchor" href="#i-can-t-attach-a-zone-to-a-product" aria-label="Permalink to &quot;I can&#39;t attach a zone to a product&quot;">​</a></h2><p>Only qualified zones can be attached. Qualify the zone in the <a href="./administration/registry.html#zones">registry</a>, or ask Product Operations.</p><h2 id="i-lost-my-authenticator-phone" tabindex="-1">I lost my authenticator phone <a class="header-anchor" href="#i-lost-my-authenticator-phone" aria-label="Permalink to &quot;I lost my authenticator phone&quot;">​</a></h2><p>Use a recovery code to sign in, then disable the app in <a href="./account.html#security">My account</a>. Without a recovery code, contact the administrator.</p><h2 id="i-get-too-many-e-mails" tabindex="-1">I get too many e-mails <a class="header-anchor" href="#i-get-too-many-e-mails" aria-label="Permalink to &quot;I get too many e-mails&quot;">​</a></h2><p>For each event, choose between the notification and the e-mail in your <a href="./notifications.html#choosing-how-you-are-notified">preferences</a>.</p><h2 id="contacts" tabindex="-1">Contacts <a class="header-anchor" href="#contacts" aria-label="Permalink to &quot;Contacts&quot;">​</a></h2><p>For a question this guide doesn&#39;t answer, contact your head of unit or the platform&#39;s general administrator. Their details are in the intranet&#39;s shared resources.</p>',19)])])}const p=a(n,[["render",i]]);export{m as __pageData,p as default};
